# Look at the distribution - maybe there's color swapping or reflection
grid = [
    [1, 6, 6, 6, 6, 6, 5, 6],
    [7, 3, 6, 7, 3, 6, 5, 6],
    [6, 6, 6, 6, 6, 6, 5, 1],
    [6, 4, 6, 5, 6, 6, 6, 6],
    [3, 4, 6, 4, 7, 1, 5, 6],
    [6, 5, 6, 3, 6, 6, 6, 5],
    [4, 3, 6, 6, 6, 6, 6, 6],
    [6, 4, 6, 4, 6, 5, 1, 1]
]

# Check horizontal/vertical reflection
# Horizontal flip (mirror left-right)
h_flip = [[grid[r][c] for c in range(7, -1, -1)] for r in range(8)]
print("Horizontal flip - special cells:")
for r in range(8):
    for c in range(8):
        if h_flip[r][c] != 6:
            print(f"  ({r},{c}): {h_flip[r][c]}")

# Vertical flip (mirror top-bottom)
v_flip = [[grid[7-r][c] for c in range(8)] for r in range(8)]
print("\nVertical flip - special cells:")
for r in range(8):
    for c in range(8):
        if v_flip[r][c] != 6:
            print(f"  ({r},{c}): {v_flip[r][c]}")

# 180 rotation
rot180 = [[grid[7-r][7-c] for c in range(8)] for r in range(8)]
print("\n180 rotation - special cells:")
for r in range(8):
    for c in range(8):
        if rot180[r][c] != 6:
            print(f"  ({r},{c}): {rot180[r][c]}")

# Let me look at whether there's a pattern about creating diagonal lines
# or clustering by diagonal

from math import floor

grid = [
    [1, 6, 6, 6, 6, 6, 5, 6],
    [7, 3, 6, 7, 3, 6, 5, 6],
    [6, 6, 6, 6, 6, 6, 5, 1],
    [6, 4, 6, 5, 6, 6, 6, 6],
    [3, 4, 6, 4, 7, 1, 5, 6],
    [6, 5, 6, 3, 6, 6, 6, 5],
    [4, 3, 6, 6, 6, 6, 6, 6],
    [6, 4, 6, 4, 6, 5, 1, 1]
]

# Check anti-diagonal sums (r + c)
print("Anti-diagonal grouping (r + c):")
anti_diag = {}
for r in range(8):
    for c in range(8):
        if grid[r][c] != 6:
            s = r + c
            if s not in anti_diag:
                anti_diag[s] = []
            anti_diag[s].append((r, c, grid[r][c]))

for s in sorted(anti_diag.keys()):
    items = anti_diag[s]
    values = [x[2] for x in items]
    print(f"  Sum={s}: positions {[(x[0],x[1]) for x in items]} -> values {values}")

# Check main diagonal differences (r - c)
print("\nMain diagonal grouping (r - c):")
diag_diff = {}
for r in range(8):
    for c in range(8):
        if grid[r][c] != 6:
            d = r - c
            if d not in diag_diff:
                diag_diff[d] = []
            diag_diff[d].append((r, c, grid[r][c]))

for d in sorted(diag_diff.keys()):
    items = diag_diff[d]
    values = [x[2] for x in items]
    print(f"  Diff={d}: positions {[(x[0],x[1]) for x in items]} -> values {values}")

